// smc-whatsapp-send (LOCAL-STAGING §7, I-48f): the shared WhatsApp sender sub-workflow. Pure functions only; the
// workflow (automation/SUB-whatsapp-send.json, generated by automation/build-sub-workflows.mjs) does the SQL and the
// Graph POST. Code node form: const L = require('lv-automation').subWhatsappSend;
//
// Accepts both caller shapes:
//   decided (I-48f) : { to, kind: template|text|interactive|media, template: 'name', variables: [..], buttons: [..],
//                       text?, interactive?, media?, lead_id?, broker_id?, correlation }
//   §7 (W19/W34)    : { broker_id, to, template: { name, body: [..], buttons: [..] }, idempotency_key?, reminder?: { text } }
// Returns from decide(): { action: 'send'|'dry'|'skip', reason?, payload?, external_id?, ... } — never throws.
import { readFileSync, existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { templateMessage, textMessage, paramCounts } from './wa.mjs';

const TEMPLATES = join(dirname(fileURLToPath(import.meta.url)), '..', 'templates');
const KINDS = ['template', 'text', 'interactive', 'media'];
export const WINDOW_MS = 24 * 3600 * 1000;

/** Digits only (the same input smc_hash_contact() hashes): '+27 82 123 4567' -> '27821234567'. */
export const digits = (v) => String(v == null ? '' : v).replace(/\D/g, '');

export function normalise(input = {}) {
  const i = input || {};
  const tpl = i.template;
  const tplName = typeof tpl === 'string' ? tpl : tpl && tpl.name;
  const kind = i.kind || (tplName ? 'template' : i.text ? 'text' : i.interactive ? 'interactive' : i.media ? 'media' : null);
  const out = {
    to: digits(i.to),
    kind,
    template: tplName || null,
    variables: Array.isArray(i.variables) ? i.variables : (tpl && Array.isArray(tpl.body) ? tpl.body : []),
    header: i.header || (tpl && tpl.header) || null,
    buttons: Array.isArray(i.buttons) ? i.buttons : (tpl && Array.isArray(tpl.buttons) ? tpl.buttons : []),
    lang: i.lang || (tpl && tpl.lang) || 'en',
    text: i.text || (i.reminder && i.reminder.text) || null,
    interactive: i.interactive || null,
    media: i.media || null,
    lead_id: i.lead_id || null,
    broker_id: i.broker_id || null,
    correlation: String(i.correlation || i.idempotency_key || ''),
  };
  const missing = [];
  if (!out.to || out.to.length < 9) missing.push('to');
  if (!KINDS.includes(out.kind)) missing.push('kind');
  if (!out.correlation) missing.push('correlation');
  if (!out.lead_id && !out.broker_id) missing.push('lead_id|broker_id');
  if (out.kind === 'template' && !out.template) missing.push('template');
  if (out.kind === 'text' && !out.text) missing.push('text');
  if (out.kind === 'interactive' && !out.interactive) missing.push('interactive');
  if (out.kind === 'media' && !(out.media && out.media.type && (out.media.link || out.media.id))) missing.push('media');
  return { ...out, valid: missing.length === 0, missing };
}

/** The submitted template (automation/templates/<name>.json) or null. */
export function templateSpec(name) {
  if (!/^[a-z0-9_]+$/.test(String(name || ''))) return null;
  const f = join(TEMPLATES, `${name}.json`);
  return existsSync(f) ? JSON.parse(readFileSync(f, 'utf8')) : null;
}

/** Expected parameter counts + the index of every dynamic button (quick replies carry a payload; URL with {{n}}). */
export function templateShape(spec) {
  const vars = (s) => new Set([...String(s || '').matchAll(/\{\{(\d+)\}\}/g)].map((m) => m[1])).size;
  const h = spec.components.find((c) => c.type === 'HEADER');
  const btns = (spec.components.find((c) => c.type === 'BUTTONS') || {}).buttons || [];
  const dynamic = [];
  btns.forEach((b, index) => {
    if (b.type === 'QUICK_REPLY') dynamic.push({ index, kind: 'quick_reply' });
    else if (b.type === 'URL' && /\{\{\d+\}\}/.test(b.url || '')) dynamic.push({ index, kind: 'url' });
  });
  return {
    counts: {
      header: !h ? 0 : h.format === 'TEXT' ? vars(h.text) : 1,
      body: vars((spec.components.find((c) => c.type === 'BODY') || {}).text),
      quick_reply: dynamic.filter((d) => d.kind === 'quick_reply').length,
      url: dynamic.filter((d) => d.kind === 'url').length,
    },
    total_buttons: btns.length,
    dynamic,
  };
}

/** Caller buttons (in order: string | {quick_reply} | {url} | {payload}) onto the template's dynamic positions. */
export function mapButtons(shape, buttons = []) {
  const out = new Array(shape.total_buttons).fill(null);
  shape.dynamic.forEach((d, k) => {
    const b = buttons[k];
    if (b == null) return;
    const v = typeof b === 'object' ? (b[d.kind] ?? b.payload ?? b.value) : b;
    if (v != null) out[d.index] = { [d.kind]: v };
  });
  return out;
}

/** Template approval from brands.template_status ({ items: [{ name, status }] }). Unknown -> not approved. */
export function templateApproved(templateStatus, name) {
  const items = (templateStatus && templateStatus.items) || [];
  const row = items.find((x) => x && x.name === name);
  return !!row && String(row.status || '').toUpperCase() === 'APPROVED';
}

/** Inside the 24-h customer-service window: last inbound (sender_type broker/client) less than 24 h ago. */
export function windowOpen(lastInboundAt, nowMs = Date.now()) {
  const t = lastInboundAt ? Date.parse(lastInboundAt) : NaN;
  return Number.isFinite(t) && nowMs - t < WINDOW_MS && t <= nowMs + 60_000;
}

/** WHATSAPP_TEST_RECIPIENTS allow-list (comma/space separated). Empty list = no restriction (production). */
export function allowListed(to, env = {}) {
  const list = String(env.WHATSAPP_TEST_RECIPIENTS || '').split(/[\s,;]+/).map(digits).filter(Boolean);
  return list.length === 0 || list.includes(digits(to));
}

/**
 * decide(n, ctx, env, nowMs)
 *   n   : normalise() output
 *   ctx : row from "Load context" { brand_id, suppressed, last_inbound_at, template_status, duplicate }
 * Order: duplicate -> suppression -> allow-list -> template/window rules -> DRY_RUN -> send.
 */
export function decide(n, ctx = {}, env = {}, nowMs = Date.now()) {
  const base = { to: n.to, kind: n.kind, template: n.template, lead_id: n.lead_id, broker_id: n.broker_id, brand_id: ctx.brand_id || null, correlation: n.correlation };
  const skip = (reason, extra = {}) => ({ ...base, action: 'skip', reason, ...extra });
  if (!n.valid) return skip('invalid_input', { missing: n.missing });
  if (ctx.duplicate) return { ...base, action: 'duplicate', reason: 'already_sent', external_id: ctx.duplicate_external_id || null };
  if (ctx.suppressed === true || ctx.suppressed === 't') return skip('suppressed');
  if (!allowListed(n.to, env)) return skip('not_allow_listed');
  const open = windowOpen(ctx.last_inbound_at, nowMs);
  let payload, sentAs = n.kind;
  if (n.kind === 'template') {
    const spec = templateSpec(n.template);
    if (!spec) return skip('unknown_template');
    if (!templateApproved(ctx.template_status, n.template)) {
      // §7 (5): template not approved yet -> session text inside the window, otherwise the email leg (caller / howzit@).
      if (n.text && open) { payload = textMessage(n.to, n.text); sentAs = 'text'; }
      else return skip('template_not_approved', { email_fallback: true, window_open: open });
    } else {
      const shape = templateShape(spec);
      const msg = templateMessage(n.to, n.template, { body: n.variables, header: n.header, buttons: mapButtons(shape, n.buttons), lang: spec.language || n.lang });
      const got = paramCounts(msg);
      const want = shape.counts;
      if (got.header !== want.header || got.body !== want.body || got.quick_reply !== want.quick_reply || got.url !== want.url) {
        return skip('param_count_mismatch', { want, got });
      }
      payload = msg;
    }
  } else {
    if (!open) return skip('outside_24h_window');
    if (n.kind === 'text') payload = textMessage(n.to, n.text);
    else if (n.kind === 'interactive') payload = { messaging_product: 'whatsapp', recipient_type: 'individual', to: n.to, type: 'interactive', interactive: n.interactive };
    else payload = { messaging_product: 'whatsapp', recipient_type: 'individual', to: n.to, type: n.media.type, [n.media.type]: n.media.id ? { id: n.media.id, ...(n.media.caption ? { caption: n.media.caption } : {}) } : { link: n.media.link, ...(n.media.caption ? { caption: n.media.caption } : {}) } };
  }
  if (String(env.DRY_RUN_SENDS || '').toLowerCase() === 'true') return { ...base, action: 'dry', sent_as: sentAs, external_id: `dry:${n.correlation}` };
  return { ...base, action: 'send', sent_as: sentAs, payload };
}

/** communications row content: never the body's personal fields (§7 (6)). */
export const logContent = (d) => (d.sent_as === 'template' || (d.kind === 'template' && d.sent_as !== 'text') ? `template:${d.template}` : `[${d.sent_as || d.kind}]`);

/** Graph response -> { ok, external_id, error }. */
export function interpret(res = {}) {
  const body = res.body !== undefined ? res.body : res;
  const id = body && body.messages && body.messages[0] && body.messages[0].id;
  if (id) return { ok: true, external_id: id, error: null };
  const e = (body && body.error) || res.error || {};
  return { ok: false, external_id: null, error: String(e.message || e.code || 'send_failed').slice(0, 300) };
}

/** Final { ok, external_id, error } for the caller. */
export function result(d = {}, r = null) {
  if (d.action === 'dry') return { ok: true, external_id: d.external_id, error: null };
  if (d.action === 'duplicate') return { ok: true, external_id: d.external_id || null, error: null, duplicate: true };
  if (d.action === 'skip') return { ok: false, external_id: null, error: d.reason, ...(d.email_fallback ? { email_fallback: true } : {}) };
  if (r) return { ok: !!r.ok, external_id: r.external_id || null, error: r.error || null };
  return { ok: false, external_id: null, error: 'not_sent' };
}
